// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Request one bounded on-demand Profile duplicate analysis
	// (POST /api/v1/matching/analyses)
	StartMatchingAnalysis(ctx context.Context, request StartMatchingAnalysisRequestObject) (StartMatchingAnalysisResponseObject, error)
	// Read one actor-scoped analysis
	// (GET /api/v1/matching/analyses/{analysis_id})
	GetMatchingAnalysis(ctx context.Context, request GetMatchingAnalysisRequestObject) (GetMatchingAnalysisResponseObject, error)
	// Cancel one queued or running actor-scoped analysis
	// (POST /api/v1/matching/analyses/{analysis_id}/cancel)
	CancelMatchingAnalysis(ctx context.Context, request CancelMatchingAnalysisRequestObject) (CancelMatchingAnalysisResponseObject, error)
	// List authorized persistent Profile duplicate review cases
	// (GET /api/v1/matching/cases)
	ListMatchingCases(ctx context.Context, request ListMatchingCasesRequestObject) (ListMatchingCasesResponseObject, error)
	// Read one authorized case with complete Profile comparison values
	// (GET /api/v1/matching/cases/{case_id})
	GetMatchingCase(ctx context.Context, request GetMatchingCaseRequestObject) (GetMatchingCaseResponseObject, error)
	// Record an explicit version-sensitive NOT_DUPLICATE decision
	// (POST /api/v1/matching/cases/{case_id}/dismiss)
	DismissMatchingCase(ctx context.Context, request DismissMatchingCaseRequestObject) (DismissMatchingCaseResponseObject, error)
	// Confirm one explicit ADMIN/SUPERADMIN Profile merge
	// (POST /api/v1/matching/cases/{case_id}/merge)
	MergeProfiles(ctx context.Context, request MergeProfilesRequestObject) (MergeProfilesResponseObject, error)
	// Preview explicit Profile field precedence and dependency movement
	// (POST /api/v1/matching/cases/{case_id}/merge-preview)
	PreviewProfileMerge(ctx context.Context, request PreviewProfileMergeRequestObject) (PreviewProfileMergeResponseObject, error)
	// Read the authorized evidence catalog and fixed runtime limits
	// (GET /api/v1/matching/catalog)
	GetMatchingCatalog(ctx context.Context, request GetMatchingCatalogRequestObject) (GetMatchingCatalogResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

